    "potere": "L'ambra poteva essere usata come componente materiale per la maggior parte degli incantesimi che avevano a che fare con le scariche elettriche, da quelli più piccoli come una presa scioccante a quelli più potenti come una catena di fulmini. Veniva anche usato per produrre l'inchiostro per scrivere tali incantesimi. L'incantesimo Banite frusta mistica utilizzava l'ambra come componente materiale. Lanciare l'incantesimo Tormiano Dardo di Gloria richiedeva l'uso di una verga d'ambra fasciata di bronzo. Versioni giganti di insetti e altri parassiti potrebbero essere magicamente collocate in un'ambra di qualità gemma per creare un amuleto d'ambra di parassiti."
