    "fonte": "Forgotten Realms Wiki",
    "fonte_url": "https://forgottenrealms.fandom.com/wiki/Chasm_creeper",
    "descrizione": "Questi bellissimi cristalli brillavano di una delicata radiazione viola. La base di cristallo aveva una tonalità lavanda più brillante e diventava più scura verso i bordi dei cristalli, diventando viola intenso.",
    "potere": ""
