    "descrizione": "Le gemme che potevano essere incantate per diventare gemme elementali includevano diamanti gialli, corindoni rossi, smeraldi e zaffiri blu.",
    "potere": "Dopo essersi rotta o frantumata, una gemma elementale rilasciava la sua magia e permetteva a chi la impugnava di evocare un elementale in modo simile all'incantesimo Evoca elementale o Evoca alleati naturali. A seconda della pietra preziosa, veniva evocato un elementale diverso: i diamanti gialli evocavano gli elementali della terra, i corindoni rossi evocavano gli elementali del fuoco, gli smeraldi evocavano gli elementali dell'acqua e gli zaffiri blu evocavano gli elementali dell'aria. Una volta rotta e utilizzata, la gemma perdeva il suo potere."
