    "descrizione": "L'Occhio di Lathander era una pietra preziosa scolpita a somiglianza del simbolo sacro di Lathander, il Portatore dell'Alba.",
    "potere": "Il gioiello di Lathander era intriso di potenti magie curative che, una volta attivate, conferivano forza vitale a un alleato, ripristinandogli una parte della vitalità. Oltre a essere resuscitato sul campo di battaglia, l'artefatto potenziava le difese dell'alleato, la destrezza nell'evitare i danni in arrivo e le sue capacità di guarigione. Quando l'Occhio di Lathander veniva utilizzato insieme al mantello e alla cintura di Lathander, le magie di tutti e tre gli artefatti funzionavano all'unisono."
