    "descrizione": "Le divinità potevano mostrare i loro poteri attraverso manifestazioni maggiori e manifestazioni minori. L'aspetto di una gemma (o di un minerale) rientrava in quest'ultima categoria. Queste pietre furono fatte apparire dalle divinità per informare i mortali di qualcosa. Potrebbe trattarsi di qualcosa di generale come il piacere o il dispiacere, ma anche qualcosa di concreto come l’esistenza di un infiltrato. I modi in cui queste gemme potevano fornire informazioni erano vari.",
