    "fonte_url": "https://forgottenrealms.fandom.com/wiki/Fingarl%27s_Flame",
    "descrizione": "Un rubino grande quanto la testa del suo proprietario, aveva una forma approssimativamente piramidale con la punta superiore curvata da un lato, che ricordava una fiamma o un corno di bue. Grazie ai suoi incantesimi brillava di una luce rossa costante.",
    "potere": "Poiché era troppo grande e ingombrante per essere indossato come gioiello, il rubino venne incantato e si librava nell'aria e seguiva il suo proprietario proprio dietro la spalla destra. Produceva anche una luce, simile al fuoco fatato con un bagliore rosso continuo. Inoltre, come misura di sicurezza, la Fiamma di Fingarl diventava incredibilmente calda ed emetteva un urlo assordante quando veniva spostata dal suo proprietario, in particolare, \"dagli occhi di Fingarl\"."
