    "descrizione": "L'opale di fuoco era una brillante forma di opale rosso-arancio che di solito era di colore solido ma poteva avere lampi dorati o verdastri. Un tipico esemplare aveva un valore base di 1.000 mo. Gli anelli con piccole gemme di opale di fuoco incastonate erano generalmente valutati 500 mo.",
    "potere": "Erano le gemme preferite da utilizzare negli elmi dello splendore. La loro affinità con l'accensione, il rilascio e il controllo del fuoco li rendeva utili nella formulazione di inchiostri per incidere pergamene, nell'incantare immersioni per creare oggetti e nel montaggio su dispositivi come punto focale di scarica."
