    "potere": "L'occhio della gemma aveva come incantesimo infravisione permanente attivo, permettendo a Gamalon Idogyr, il suo proprietario, di vedere anche nell'oscurità più profonda del Sottosuolo. Inoltre, la gemma di Gamalon aveva un incantesimo permanente di individuazione magica inserito nei suoi incantesimi."
