    "descrizione": "I granati erano disponibili in molti colori (vedi galleria) ma, a partire dall'Anno della Magia Selvaggia, 1372 CV, la tonalità viola era la più preziosa e veniva chiamata rodolite mentre le altre varietà caddero in disgrazia e furono valutate nella fascia di prezzo delle pietre elaborate. Negli anni successivi, anche le pietre di colore viola diminuirono di valore. I granati formavano cristalli isometrici con dodici o ventiquattro facce, sebbene siano state trovate versioni con trentasei o quarantotto facce.",
