    "descrizione": "Questi oggetti erano sempre gioielli del valore di almeno 5.000 mo senza l'incantesimo magico.",
    "potere": "Dopo essere stato trasportato per due settimane, una gemma di intuizione ha iniziato a rendere più facile per il suo portatore comprendere le cose e ha potenziato la sua memoria. Dopo aver posseduto la gemma per tre mesi, il portatore sarebbe effettivamente diventato più intelligente e saggio. Se un individuo non portasse più con sé la gemma dopo quel periodo di tre mesi, la sua intelligenza rimarrebbe potenziata, ma la sua saggezza tornerebbe alla normalità. Un gioiello di intuizione potrebbe fornire questi benefici solo una volta per individuo."
