    "descrizione": "Questa pietra semipreziosa era marrone e opaca (a volte rossastra o verdastra) e conteneva lustrini argentati. Era raro trovare un pezzo senza difetti di diametro superiore a 13 mm e, di conseguenza, la pietra produceva piccole gemme. Una tipica pietra aveva un valore base di 50 mo.",
    "potere": "Portare o indossare una di queste gemme rendeva il portatore non rilevabile dall'incantesimo guardia della viverna. Nel linguaggio comune questa proprietà era conosciuta come protezione della viverna."
