    "fonte_url": "https://forgottenrealms.fandom.com/wiki/Iol",
    "descrizione": "Questa pietra semipreziosa aveva prevalentemente una tonalità blu, ma il suo colore cambiava con l'angolo di visione, dal blu scuro al giallo paglierino. Le iole piccole potevano essere trasparenti ma le pietre più grandi tendevano ad avere inclusioni che potevano causare un effetto a stella o, nel caso di cristalli di ematite intrappolati, un lampo di colore dorato molto simile alle pietre solari. Le iol venivano solitamente tagliate sfaccettate per mostrare al meglio il cambiamento di colore della pietra. Una tipica iol aveva un valore base di 50 mo.",
    "potere": "Le pietre Iol erano il componente migliore da utilizzare nella produzione delle pietre Ioun."
