    "tipo_gemma": "reame",
    "fonte": "Forgotten Realms Wiki",
    "fonte_url": "https://forgottenrealms.fandom.com/wiki/Koh_Nur",
    "descrizione": "La luce emessa da Koh Nur era il metodo per cronometrare il Settuplo Labirinto e l'intera distesa del Grande Scavo Tetro. La luce illuminava anche l'intera area. Due volte al giorno Koh Nur cambiava colore, dall'arancione chiaro al viola intenso. L'inizio del mattino è stato segnato dalla luce arancione che gocciolava dalla Montagna della Luce ed è durato circa 13 ore, a quel punto la luce è cambiata in viola ed è durata lo stesso periodo di tempo.",
    "potere": ""
