    "descrizione": "Queste gemme scintillanti emettevano un bagliore tremolante che più di una volta attirò sfortunati viaggiatori del Sottosuolo verso la loro rovina. Molti confondevano le candele di Lolth con le lanterne tremolanti dei compagni di viaggio nell'oscurità della metropolitana.",
    "potere": ""
