    "descrizione": "La Pipestone era una pietra tenera, facilmente scolpita. Si è verificato nei colori dal marrone al rosso. Una pietra tipica aveva un prezzo di 1 mo per libbra (4 ma 5 mo per chilogrammo).",
    "potere": "Gli incantesimi da mago che richiedevano un qualche tipo di legno come componente materiale potevano invece utilizzare la pietra piperita. Questo non funzionava con gli incantesimi divini."
