    "fonte_url": "https://forgottenrealms.fandom.com/wiki/Selu%27kiira",
    "descrizione": "Una selu'kiira era conosciuta anche come \"Gemma dell'Alto Sapere\". Uno sarebbe stato realizzato con una tormalina arcobaleno ed era tipicamente un cristallo scintillante più grande, più ornato e sfaccettato di una normale kiira. Una selu'kiira cambiava colore nel tempo a seconda di quanti ricordi aveva assorbito. I colori cambiarono dalle tonalità del blu al verde, al nero, al marrone, all'arancione e infine ad una tonalità rosso brillante dopo più di 3000 anni di età.",
