    "potere": "Mentre trasportava o indossava una di queste pietre, il quarzo rosa stellato aveva la possibilità di deviare un incantesimo diretto al portatore. A causa di questa proprietà, questa pietra semipreziosa era una componente magica alternativa per tutti gli incantesimi di abiurazione e per qualsiasi magia divina della sfera di protezione che potesse utilizzare una componente materiale che non fosse stata appositamente preparata per un particolare incantesimo."
