    "descrizione": "La varietà più comune di questa pietra ornamentale era morbida e poteva essere tagliata solo a cabochon, ma si presentava in una varietà incolore o leggermente verdastra che era di grado sfaccettato. I cabochon di pietra solare avevano raramente un diametro superiore a tre quarti di pollice (2 cm) e presentavano scintillanti inclusioni rosse o arancioni sospese in una matrice quasi incolore, che conferiva alla pietra complessiva una calda tonalità dorata o bruno-rossastra. Una tipica pietra aveva un valore base di 10 mo.",
    "potere": "Le pietre solari potevano essere trasformate in talismani, solitamente sotto forma di gioielli, che agivano sui non morti proprio come la piena luce del sole. Un talismano di pietra solare doveva essere caricato rimanendo in pieno sole per almeno un giorno (circa sei ore di esposizione continua). Successivamente, il talismano poteva essere indossato e rimaneva dormiente finché chi lo indossava non veniva attaccato (toccato fisicamente) con successo da una creatura non morta."
