    "descrizione": "Il Tabasheer è stato trovato in pepite irregolari che di solito venivano levigate e poi lucidate fino a ottenere una lucentezza vellutata. Venivano indossati in anelli e decoravano le frange di scialli e pettorali, soprattutto nel sud, dove questa pietra preziosa veniva utilizzata come valuta negli accordi commerciali, soprattutto nei baratti con le tribù barbare del nord. Un tipico esemplare ha un valore base di 50 mo.",
    "potere": "Macinato in polvere e posto sulla lingua o in una ferita aperta, il tabasheer ha avuto un effetto notevole sul soggetto quando gli veniva lanciato Cura ferite leggere: il destinatario di questo trattamento otteneva un temporaneo aumento di salute che durava per 24 ore o fino a quando la salute veniva persa a causa di successive lesioni, veleno o malattie."
