    "fonte_url": "https://forgottenrealms.fandom.com/wiki/Thuparlial",
    "descrizione": "Thuparlial era una pietra preziosa dura, resistente e traslucida che variava di colore dal verde intenso al giallo verdastro pallido e dal giallo al marrone. Thuparlial veniva tagliato sfaccettato se di colore chiaro ma altrimenti trasformato in cabochon. Era considerata una pietra ornamentale e un tipico esemplare aveva un valore base di 10 mo.",
    "potere": "In polvere, questo minerale veniva utilizzato negli inchiostri per creare incantesimi pirotecnici e riscaldare i metalli. I maghi rossi che avevano accesso a grandi quantità di thuparlial sperimentarono l'utilizzo come ingrediente sostitutivo per molti incantesimi basati sul fuoco e sul calore. Non si sapeva se ci fossero riusciti."
