    "descrizione": "Questa gemma si presentava in tonalità dal giallo pallido al giallo intenso e veniva facilmente lavorata, anche da persone non qualificate, in grandi cabochon o gemme sfaccettate che erano popolari in gioielleria. Un tipico esemplare aveva un valore base di 100 mo.",
    "potere": "Ulvaen era apprezzato per le sue proprietà curative e rigenerative. Se posto in una ferita, un cristallo di ulvaen si scioglierebbe in pochi minuti e rilascerebbe la sua magia curativa. La quantità di guarigione era completamente casuale per una determinata pietra. Mentre la magia curativa diffondeva la ferita, avrebbe prima tentato di fermare qualsiasi sanguinamento. Se ciò avesse avuto successo, gli organi danneggiati avrebbero avuto la possibilità di essere ripristinati. Se ciò avesse successo, ogni ferita aperta potrebbe chiudersi."
