    "descrizione": "Questa pietra era traslucida e arrivava a sfumature pallide di verde giallastro. Quando venivano tagliati a cabochon e lucidati, occasionalmente mostravano bande o anelli grigi e gialli (\"occhi\"). Una tipica pietra aveva un valore base di 10 mo.",
    "potere": "La variscite era velenosa per i licantropi e, se immessa nel flusso sanguigno sulla punta di un'arma, causava il triplo del danno normale per quel colpo. Una volta che un licantropo veniva infettato dalla variscite, un'ulteriore esposizione non causava ulteriori danni finché il soggetto non si riprendeva, un processo che richiedeva 24 ore intere. L'infezione potrebbe verificarsi anche se una pietra variscite, ad esempio montata su un anello o altro gioiello, venisse premuta in una ferita aperta su un licantropo o toccata sulla lingua della creatura."
