    "descrizione": "Trovata in depositi mescolati con altri minerali e occasionalmente di dimensioni eccezionali (fino al pugno umano), questa pietra ornamentale era solitamente tagliata a cabochon e lucidata, o sfaccettata in stile baguette. Una tipica pietra aveva un valore base di 10 mo. Le pietre di violino erano considerate sacre dai seguaci di Ghaunadaur: adatte al sacrificio, o da consacrare per l'uso, o riconosciute come vantaggi o presagi quando venivano trovate.",
    "potere": "Questa gemma era a prova di putrefazione della mummia. Una creatura con la putrefazione della mummia doveva solo toccare un cristallo di violino e la putrefazione della mummia veniva rimossa. Il violino venne completamente consumato da questo processo. Se questa pietra entrava in contatto con una vera mummia, scoppiava e la danneggiava. Se una mummia veniva distrutta dal contatto con il violino, la polvere di mummia risultante era inerte e non poteva essere utilizzata come componente di incantesimi o per altri scopi magici."
