    "descrizione": "Questa pietra ornamentale era una varietà di ossidiana formata da piccoli pezzi di pietra cementati insieme dal calore e dalla pressione in una massa globulare, le cui giunture apparivano come sottili linee simili a ragnatele. Di solito era nero, le cuciture a volte erano bianche, ma erano note varietà marroni, bruno-rossastre e rosso ruggine con linee di ragnatela di colore più chiaro.",
    "potere": "Questa pietra offriva protezione contro gli inquinanti atmosferici e i gas se indossata a diretto contatto con la pelle. Alcuni gioiellieri modellavano pietre di ragnatela cadute in fasce sotto l'ascella che venivano indossate intorno alla spalla per mantenere il contatto con la pelle. Quando chi la indossava veniva esposto a gas velenosi, fumo o spore disperse nell'aria, la webpietra vaporizzava in esplosioni irregolari, proteggendo chi la indossava dagli effetti dannosi fino all'esaurimento della scorta o fino al termine dell'esposizione."
