    "descrizione": "La witherite è stata trovata in grandi depositi fibrosi contenenti zone di materiale traslucido di qualità gemma. Se abbastanza grandi, producevano gemme sfaccettate dal giallo pallido al biancastro. Raramente, la witherite si presentava in grappoli di cristalli giallastri traslucidi che producevano anche gemme sfaccettate. Un tipico esemplare aveva un valore base di 50 mo.",
    "potere": "La Witherite conferiva una certa protezione o addirittura immunità agli effetti debilitanti degli incantesimi di guarigione inversa negromantica e di alcuni attacchi psionici. La pietra doveva essere montata in una speciale montatura di elettro che consentisse il contatto diretto della pelle con la witherite. Si sapeva che questo funzionava almeno per gli umani e i semiumani."
