    "descrizione": "Queste pietre ornamentali sono state trovate in grandi depositi e potevano essere tagliate in blocchi di quasi un piede cubo (27.000 centimetri cubi) quando venivano estratte. In genere veniva tagliato a cabochon e richiedeva una lucidatura da discreta a buona. Una tipica pietra aveva un valore base di 10 mo.",
    "potere": "Quando la pietra delle meraviglie entrava in contatto diretto con un oggetto magico, un essere incantato o un oggetto ordinario che portava un incantesimo, emetteva uno strano bagliore blu reale o blu-verde per un massimo di venti minuti. Pertanto veniva utilizzato come rilevatore di magia, ma più spesso veniva utilizzato come intarsio in mobili e pannelli di pregio per fornire una nuova illuminazione d'atmosfera per eventi sociali spensierati come balli, feste e feste."
