    "descrizione": "I cristalli di Zendalure potevano essere trovati in luoghi dove la lava si era raffreddata ed era diventata solida. Questi cristalli macchiati di colore blu-bianco formavano noduli a forma di uovo di circa 2-6 pollici (da 5 a 15 cm) di diametro e potevano essere lucidati fino a ottenere una finitura a specchio. Venivano spesso usati come intarsi o tagliati in piccoli cabochon per anelli, orecchini e pendenti. Un tipico esemplare aveva un valore base di 1.000 mo.",
    "potere": "Zendalure potrebbe essere trasformato in uno sciroppo frantumando le pietre in polvere e mescolandole con acqua. Questo sciroppo potrebbe proteggere completamente e indefinitamente la carne e le ossa da ogni putrefazione e decomposizione. La carne o le parti del corpo dovevano essere completamente immerse nella miscela e non consentite l'esposizione diretta alla luce solare. Questo conservante era noto per mantenere fresca la carne di mammiferi, rettili o uccelli. Uno zendalure era necessario come parte del processo per creare un terribile guardiano."
