    "descrizione": "Ziose era un minerale raro che produceva pietre sfaccettate che brillavano di tre colori diversi a seconda di come la luce si rifrangeva attraverso di esse o da quale angolazione venivano osservate: viola, blu e rosso, o viola, verde e rosso (vedi Galleria). Esemplari molto grandi (delle dimensioni di un pugno, di un piede o di una testa umana) di queste pietre fantasiose venivano talvolta trovati e apprezzati per l'uso in ciondoli da umani, semiumani e umanoidi molto alti. Una tipica pietra aveva un valore base di 100 mo.",
    "potere": "Una gemma ziosa potrebbe lanciare molteplici raffiche di dardi magici al comando dell'ultima creatura che la tocca, a condizione che quella creatura abbia intelligenza e conoscenza di questa capacità. Questo essere doveva trovarsi a pochi metri dalla gemma e doveva solo volere che ciò accadesse. Le salve di missili continuavano per alcuni minuti e poi cessavano. Lo ziose non poteva essere riattivato finché non avesse avuto il tempo di ricaricarsi."
